2: const fs = require('fs');
3: const path = require('path');
4: const { parse } = require('./toml');
5: 
6: const HINTS = [
7:   ['Flask(', 'flask'],
8:   ['FastAPI(', 'fastapi'],
9:   ['import streamlit', 'streamlit'],
10:   ['import gradio', 'gradio'],
11: ];
12: 
13: function frameworkOf(source) {
14:   for (const [hint, fw] of HINTS) if (source.includes(hint)) return fw;
15:   return 'script';
16: }
17: 
18: // Detection order per SCOPE.md: small.toml -> --entry -> framework hint -> filename
19: // convention -> only .py file -> fail with the one-line fix.
20: function detect(dir, flags = {}) {
21:   const tomlPath = path.join(dir, 'small.toml');
22:   const config = fs.existsSync(tomlPath) ? parse(fs.readFileSync(tomlPath, 'utf8')) : {};
23:   const name = config.name || path.basename(dir).toLowerCase().replace(/[^a-z0-9-]/g, '-');
24:   const pick = (entry, via) => {
25:     const full = path.join(dir, entry);
26:     if (!fs.existsSync(full)) throw new Error(`entry ${entry} (via ${via}) does not exist`);
27:     const source = fs.readFileSync(full, 'utf8');
28:     return { name, entry, framework: config.framework || frameworkOf(source), via, config };
29:   };
30:   if (config.entry) return pick(config.entry, 'small.toml');
31:   if (flags.entry) return pick(flags.entry, '--entry');
32:   const pys = fs.readdirSync(dir).filter((f) => f.endsWith('.py'));
33:   for (const f of pys) {
34:     if (frameworkOf(fs.readFileSync(path.join(dir, f), 'utf8')) !== 'script') return pick(f, 'framework hint');
35:   }
36:   for (const f of ['app.py', 'main.py', 'server.py']) {
37:     if (pys.includes(f)) return pick(f, 'filename convention');
38:   }
39:   if (pys.length === 1) return pick(pys[0], 'only .py file');
40:   throw new Error('cannot find the app entry — add entry = "app.py" to small.toml');
41: }
42: 
43: module.exports = { detect, frameworkOf };","packages/cli/lib/init.js":"1: 'use strict';
2: const fs = require('fs');
3: const path = require('path');
4: const { detect } = require('./detect');
5: 
6: // os.environ["X"], os.environ.get("X"), os.getenv("X")
7: const ENV_RE = /os\.environ\[\s*["']([A-Za-z_]\w*)["']\s*\]|os\.(?:getenv|environ\.get)\(\s*["']([A-Za-z_]\w*)["']/g;
8: 
9: // Write small.toml from detection. Returns false when the entry could not be determined.
10: function init(dir, { force = false } = {}) {
11:   const tomlPath = path.join(dir, 'small.toml');
12:   if (fs.existsSync(tomlPath) && !force) {
13:     console.log('small.toml already exists — use --force to overwrite');
14:     return true;
15:   }
16: 
17:   let app = null;
18:   try {
19:     app = detect(dir);
20:   } catch {}
21:   const name = (app && app.name) || path.basename(dir).toLowerCase().replace(/[^a-z0-9-]/g, '-');
22:   const required = [];
23:   if (app) {
24:     const source = fs.readFileSync(path.join(dir, app.entry), 'utf8');
25:     for (const m of source.matchAll(ENV_RE)) {
26:       const v = m[1] || m[2];
27:       if (!required.includes(v)) required.push(v);
28:     }
29:   }
30:   const hasReqs = fs.existsSync(path.join(dir, 'requirements.txt'));
31: 
32:   const lines = [`name = "${name}"`];
33:   lines.push(app ? `entry = "${app.entry}"` : 'entry = ""                     # fill in: your app\'s main .py file');
34:   lines.push(`framework = "${app ? app.framework : ''}"`);
35:   if (hasReqs) lines.push('', '[deps]', 'file = "requirements.txt"');
36:   lines.push('', '[secrets]');
37:   lines.push(required.length ? `required = [${required.map((n) => `"${n}"`).join(', ')}]` : 'required = []                  # env vars this app reads — fill in');
38:   lines.push('', '[access]', 'visibility = "domain"', '');
39:   fs.writeFileSync(tomlPath, lines.join('\n'));
40: 
41:   console.log(`✓ name: ${name}`);
42:   if (app) console.log(`✓ entry: ${app.entry} (${app.framework})`);
43:   if (hasReqs) console.log('✓ deps: requirements.txt');
44:   if (required.length) console.log(`✓ secrets: ${required.join(', ')} (read by ${app.entry})`);
45:   console.log('✓ visibility: domain');
46:   console.log('✓ wrote small.toml');
47:   if (!app) console.log('✗ could not find the entry file — fill in entry = "your-app.py" in small.toml');
48:   return !!app;
49: }
50: 
51: module.exports = { init };","skills/small/SKILL.md":"1: ---
2: name: small
3: description: Deploy the Python tool you just built so colleagues can use it. Use when the user says "share this", "deploy this", "let my team use this", or finishes an internal tool that lives only on this machine.
4: ---
5: 
6: # small — share a Python tool in one command
7: 
8: When the user asks to share or deploy a Python app you built:
9: 
10: 1. In the app directory, run:
11: 
12: ```
13: small init
14: ```
15: 
16: It writes `small.toml` from what it detects: entry file, framework,
17: `requirements.txt`, and env vars the code reads (pre-filled into
18: `[secrets] required`). It never overwrites an existing `small.toml`
19: (`--force` to regenerate).
20: 
21: 2. Open `small.toml` and fill in anything marked `# fill in` — the entry file
22:    if it could not be detected, and any secret names the scan missed.
23: 
24: 3. If the app reads env vars, make sure they are in `.env` (never commit it).
25: 
26: 4. Run:
27: 
28: ```
29: small deploy --env .env
30: ```
31: 
32: (`small deploy` runs init itself when no `small.toml` exists, but running
33: init first lets you review the file.)
34: 
35: 5. Print the URL from the output. Stop. Do not build a Dockerfile, do not
36:    suggest hosting options, do not add auth — small already put the app behind
37:    a work-email login.
38: 
39: To give someone access when visibility is private, or edit rights:
40: 
41: ```
42: small share [REDACTED]          # view
43: small share [REDACTED] --edit     # can redeploy
44: ```
45: 
46: If `small` is not installed: `npm i -g small-deploy`. If not logged in the
47: deploy fails with "run small login" — have the user run `small login`
48: interactively (it emails them a 6-digit code).
49: 
50: Apps are served under a path prefix, so use **relative URLs** in HTML
51: (`action="inc"`, `href="page"`, `redirect(".")`) — absolute `/paths` break
52: behind the proxy."}},"question":{"category":"why","forbidden":["Say users must always hand-author a complete small.toml before any command can help."],"id":"s03-q1","name":"init purpose","required":["Explain that users should not need to know/write the TOML format.","Explain that automatic init preserves the one-command common deployment path."],"text":"What user problem was small init meant to solve, and why does deploy invoke it automatically?"}}
